RENORMALIZATION_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>NRRF781 — Relative Renormalization Closure</title>
<style>
:root{color-scheme:dark;font-family:Inter,system-ui,sans-serif;--bg:#070a0f;--panel:#101722;--line:#29384b;--text:#edf4fb;--muted:#92a2b4;--open:#e2b75c;--ok:#5bd09a}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -20%,#263c57,#080c12 45%,#05070a);color:var(--text)}header{padding:20px 24px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:20px;align-items:center;background:#080d14e8;position:sticky;top:0;z-index:3}h1{font-size:20px;margin:0}header p{margin:5px 0 0;color:var(--muted);font-size:12px}a{color:#b9d9ff;text-decoration:none}.layout{display:grid;grid-template-columns:minmax(330px,430px) 1fr;min-height:calc(100vh - 82px)}aside{padding:18px;border-right:1px solid var(--line);background:#0a1018cc}.main{padding:18px}.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px;margin-bottom:14px}.card h2{font-size:13px;text-transform:uppercase;letter-spacing:.09em;color:#a9b9ca;margin:0 0 12px}.field{margin:10px 0}.field label{display:block;font-size:10px;color:var(--muted);margin-bottom:5px}input,textarea,select,button{font:inherit;color:inherit}input,textarea,select{width:100%;background:#070c12;border:1px solid #314258;border-radius:9px;padding:9px}textarea{min-height:105px;resize:vertical;font-family:ui-monospace,SFMono-Regular,monospace;font-size:11px}button{border:1px solid #bcd0e5;background:#e7f0f8;color:#081019;border-radius:9px;padding:9px 12px;font-weight:700;cursor:pointer}.row{display:flex;gap:8px}.row>*{flex:1}.note{font-size:11px;color:var(--muted);line-height:1.5}.stats{display:grid;grid-template-columns:repeat(5,minmax(90px,1fr));gap:8px}.stat{background:#0b1119;border:1px solid var(--line);border-radius:10px;padding:10px}.stat strong{font-size:18px;display:block}.stat span{font-size:9px;color:var(--muted);text-transform:uppercase}.family{border:1px solid var(--line);border-radius:12px;padding:13px;margin:10px 0;background:#0b1119}.family h3{margin:0;font-size:15px}.badges{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0}.badge{font-size:9px;border:1px solid #43546a;border-radius:999px;padding:4px 7px}.badge.ok{border-color:#32765a;color:#86e2b7}.badge.open{border-color:#8c7136;color:#f0ce81}.matrix{overflow:auto;border:1px solid #29384a;border-radius:9px;margin-top:10px}table{border-collapse:collapse;width:100%;font-size:10px}th,td{padding:7px 8px;border-bottom:1px solid #233044;border-right:1px solid #233044;text-align:right}th:first-child,td:first-child{text-align:left}.mono{font-family:ui-monospace,SFMono-Regular,monospace}.empty{padding:30px;text-align:center;color:var(--muted)}#toast{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);background:#101923;border:1px solid #40546c;border-radius:10px;padding:10px 14px;opacity:0;transition:.2s;pointer-events:none}#toast.show{opacity:1}@media(max-width:900px){.layout{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line)}.stats{grid-template-columns:repeat(2,1fr)}}
</style>
</head>
<body>
<header><div><h1>NRRF781 — Relative Renormalization Closure</h1><p>Common divergence → rigid pairwise relation → scheme-free OPEN return. Absolute level is never selected.</p></div><nav><a href="/">Supernet</a> · <a href="/docs">API</a></nav></header>
<div class="layout">
<aside>
<div class="card"><h2>Integrate a regularized family</h2><form id="familyForm">
<div class="field"><label>Name</label><input id="familyName" value="common-divergence family" required /></div>
<div class="row"><div class="field"><label>Author</label><input id="author" value="participant" required /></div><div class="field"><label>Tolerance</label><input id="tolerance" value="0" /></div></div>
<div class="field"><label>Cutoff labels (JSON)</label><textarea id="cutoffs">["0","1","2"]</textarea></div>
<div class="field"><label>Member amplitudes (JSON)</label><textarea id="members">{"A":["10","11","12"],"B":["13","14","15"],"C":["7","8","9"]}</textarea></div>
<button type="submit">Integrate family</button></form><p class="note">The runtime checks only the submitted cutoff chart. A constant pairwise difference produces a rigidity receipt and determined relative closure, still OPEN and without TRUE.</p></div>
<div class="card"><h2>Add a scheme chart</h2><form id="schemeForm"><div class="field"><label>Family</label><select id="familySelect"></select></div><div class="field"><label>Scheme name</label><input id="schemeName" value="reference subtraction" /></div><div class="field"><label>Counterterm (JSON)</label><textarea id="counterterm">["10","11","12"]</textarea></div><div class="field"><label>Common shift probe</label><input id="shiftProbe" value="1" /></div><button type="submit">Add noncanonical chart</button></form><p class="note">Shifting the counterterm moves every absolute displayed value while leaving the relative closure unchanged.</p></div>
</aside>
<main class="main"><div class="card"><h2>Live field</h2><div class="stats" id="stats"></div></div><div class="card"><h2>Families and closures</h2><div id="families" class="empty">No regularized families yet.</div></div></main>
</div><div id="toast"></div>
<script>
const $=id=>document.getElementById(id);let field={families:[],schemes:[],stats:{}};
function toast(message){const t=$('toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
async function request(url,options={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...options});if(!r.ok)throw new Error((await r.json()).detail||r.statusText);return r.json()}
function matrixTable(f){const names=f.universality.member_names,m=f.universality.pairwise_differences;return `<div class="matrix"><table><thead><tr><th>Δ</th>${names.map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${names.map(a=>`<tr><th>${a}</th>${names.map(b=>`<td class="mono">${m[a][b]}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function render(){const s=field.stats||{};$('stats').innerHTML=[['families',s.families||0],['determined',s.determined_closures||0],['open',s.open_universality||0],['schemes',s.schemes||0],['admissible',s.admissible_schemes||0]].map(([k,v])=>`<div class="stat"><strong>${v}</strong><span>${k}</span></div>`).join('');$('familySelect').innerHTML=(field.families||[]).map(f=>`<option value="${f.id}">${f.name}</option>`).join('');if(!field.families?.length){$('families').className='empty';$('families').textContent='No regularized families yet.';return}$('families').className='';$('families').innerHTML=field.families.map(f=>{const u=f.universality,schemes=(field.schemes||[]).filter(x=>x.family_id===f.id);return `<div class="family"><h3>${f.name}</h3><div class="badges"><span class="badge ${u.relative_closure_determined?'ok':'open'}">${f.status}</span><span class="badge">cutoffs ${f.cutoff_labels.length}</span><span class="badge">absolute level: undetermined</span><span class="badge">truth: not issued</span></div><div class="note">reference chart: ${u.reference_member}; max drift: <span class="mono">${u.maximum_drift}</span>; scheme-free: ${u.scheme_free}; limit-free: ${u.limit_free}</div>${matrixTable(f)}${u.obstructions.length?`<pre class="note mono">${JSON.stringify(u.obstructions,null,2)}</pre>`:''}<div class="note" style="margin-top:9px">scheme charts: ${schemes.length}${schemes.map(x=>`<br>• ${x.name}: admissible=${x.evaluation.admissible_scheme}, absolute moved=${x.evaluation.shift_moves_absolute_values}, relative preserved=${x.evaluation.shift_preserves_relative_closure}`).join('')}</div></div>`}).join('')}
async function refresh(){try{field=await request('/network/renormalization/field');render()}catch(e){toast(e.message)}}
$('familyForm').addEventListener('submit',async e=>{e.preventDefault();try{await request('/network/renormalization/families',{method:'POST',body:JSON.stringify({name:$('familyName').value,authored_by:$('author').value,tolerance:$('tolerance').value,cutoff_labels:JSON.parse($('cutoffs').value),members:JSON.parse($('members').value)})});toast('Family integrated');await refresh()}catch(err){toast(err.message)}})
$('schemeForm').addEventListener('submit',async e=>{e.preventDefault();const id=$('familySelect').value;if(!id)return toast('Create a family first');try{await request(`/network/renormalization/families/${id}/schemes`,{method:'POST',body:JSON.stringify({name:$('schemeName').value,authored_by:$('author').value,counterterm:JSON.parse($('counterterm').value),shift_probe:$('shiftProbe').value})});toast('Scheme chart added');await refresh()}catch(err){toast(err.message)}})
refresh();setInterval(refresh,5000);
</script>
</body></html>'''
